  definitionSubstitutions: unknown;
  /** Description of the flow */
  description: string;
  /** ARN of a IAM role */
  executionRoleArn: string;
  /** Identifier for a Flow */
  id: string;
  /** Name for the flow */
  name: string;
  /** Schema Type for Flow APIs */
  status: string;
  /** A map of tag keys and values */
  tags: unknown;
  /** A map of tag keys and values */
  testAliasTags: unknown;
  /** Time Stamp. */
  updatedAt: string;
  /** List of flow validations */
  validations: Flow_Validations[];
  /** Draft Version. */
